A.aft=new B.ak("mupirocin","Mupirocin 2% Ointment",A.b5G,"\u0e21\u0e34\u0e27\u0e1e\u0e34\u0e42\u0e23\u0e0b\u0e34\u0e19",A.bE,A.B,A.bmi,null,A.a_,A.B,null,!1,!1,!1,!1,null,null,A.B,"Effective against MRSA skin infections. Apply thin layer to affected area TID for 5-14 days.","\u0e22\u0e32\u0e06\u0e48\u0e32 MRSA \u0e17\u0e32\u0e1c\u0e34\u0e27\u0e2b\u0e19\u0e31\u0e07 \u0e17\u0e32\u0e1a\u0e32\u0e07\u0e46 \u0e27\u0e31\u0e19\u0e25\u0e30 3 \u0e04\u0e23\u0e31\u0e49\u0e07 \u0e15\u0e34\u0e14\u0e15\u0e48\u0e2d\u0e01\u0e31\u0e19 5-14 \u0e27\u0e31\u0e19","","",null,null,null,A.Z)
